function spiralOrder(matrix) {
  const r = matrix.length, c = matrix[0].length, seen = matrix.map(row => row.map(() => false));
  const dr = [0, 1, 0, -1], dc = [1, 0, -1, 0], out = [];
  let i = 0, j = 0, d = 0;
  for (let k = 0; k < r * c; k++) {
    out.push(matrix[i][j]); seen[i][j] = true;
    const ni = i + dr[d], nj = j + dc[d];
    if (ni < 0 || ni >= r || nj < 0 || nj >= c || seen[ni][nj]) d = (d + 1) % 4;
    i += dr[d]; j += dc[d];
  }
  return out;
}
